package com.msarobotika.cyberdeck
import org.junit.Assert.*
import org.junit.Test
class AgentVoicePolicyTest {
 @Test fun dictationIsADraftWithExactTargetsAndHardLimits(){assertEquals("Revisa https://example.com/Path?q=Own",AgentVoicePolicy.draft("  Revisa https://example.com/Path?q=Own  "));for(raw in listOf(" ","x".repeat(801),"text\u0000more")){assertTrue(runCatching{AgentVoicePolicy.draft(raw)}.isFailure)}}
 @Test fun emptyOrUnexecutedPlanDoesNotInventResults(){assertTrue(AgentVoicePolicy.brief(AgentSession(plan=AgentPlan(listOf(AgentTool.PHONE)))).contains("Todavía no hay"))}
 @Test fun readingDoesNotSpeakTargetsFieldsQrOrGeneratedAnswers(){val p=AgentPlan(listOf(AgentTool.LINK,AgentTool.ANALYST));val steps=p.steps.map{AgentStepResult(it,result=DiagnosticResult(it.wire,"PRIVATE_TARGET","now","PRIVATE_PAYLOAD",listOf("secret" to "PRIVATE_FIELD")))};val text=AgentVoicePolicy.brief(AgentSession(plan=p,results=steps,run=AgentRun(p,"start","end",steps)));assertFalse(text.contains("PRIVATE"));assertTrue(text.contains("Un resultado es una interpretación"));assertTrue(text.contains("no acredita seguridad"))}
 @Test fun nativeSummariesRemainBoundedAndManualStepsAreNotReadAsFacts(){val p=AgentPlan(listOf(AgentTool.PHONE,AgentTool.CONNECTION));val steps=listOf(AgentStepResult(AgentTool.PHONE,manual=true,result=DiagnosticResult("manual","own","now","MANUAL_VALUE",emptyList())),AgentStepResult(AgentTool.CONNECTION,result=DiagnosticResult("connection","own","now","NATIVE_OBSERVATION",listOf("secret" to "PRIVATE_FIELD"))));val text=AgentVoicePolicy.brief(AgentSession(plan=p,results=steps,run=AgentRun(p,"s","e",steps)));assertTrue(text.contains("Un paso fue confirmado manualmente"));assertTrue(text.contains("NATIVE_OBSERVATION"));assertFalse(text.contains("MANUAL_VALUE"));assertFalse(text.contains("PRIVATE_FIELD"));assertTrue(text.length<=1100)}
 @Test fun waitingAndErrorAreNotSpokenAsCompletion(){val p=AgentPlan(listOf(AgentTool.NFC));for(step in listOf(AgentStepResult(AgentTool.NFC,awaiting=true),AgentStepResult(AgentTool.NFC,error="PRIVATE_ERROR"))){val text=AgentVoicePolicy.brief(AgentSession(plan=p,results=listOf(step),run=AgentRun(p,"s","e",listOf(step))));assertTrue(text.contains("0 de 1"));assertFalse(text.contains("PRIVATE_ERROR"));assertFalse(text.contains("Revisión finalizada"))}}
}
